SELECT DISTINCT r.role_code
FROM iam_user_role ur

JOIN iam_role r ON r.id = ur.role_id
WHERE ur.tenant_id = #{tenantId}
  AND ur.user_id = #{userId}
  AND ur.deleted_at IS NULL
  AND (ur.expires_at IS NULL OR ur.expires_at > now())
  AND r.tenant_id = #{tenantId}
  AND r.deleted_at IS NULL
  AND r.status = 'ACTIVE'

SELECT count(DISTINCT feature_code)
FROM iam_tenant_feature
WHERE tenant_id = #{tenantId}
  AND enabled = true
  AND feature_code IN

      #{featureCode}

SELECT count(*)
FROM iam_user
WHERE tenant_id = #{tenantId}
  AND id = #{userId}
  AND status = 'ACTIVE'
  AND deleted_at IS NULL

SELECT id invitation_id, user_id, email, status, expires_at, created_at,
  'NOT_QUEUED' delivery_status, 0 delivery_attempts, NULL delivery_error
FROM iam_user_invitation WHERE tenant_id = #{tenantId} AND id = #{invitationId}

SELECT count(*)
FROM iam_role
WHERE tenant_id = #{tenantId}
  AND id = #{roleId}
  AND role_type = 'business'
  AND deleted_at IS NULL

SELECT count(DISTINCT m.id) FROM iam_menu m LEFT JOIN iam_menu_feature mf ON mf.menu_id = m.id LEFT JOIN iam_tenant_feature tf ON tf.tenant_id = #{tenantId} AND tf.feature_code = mf.feature_code WHERE m.id IN
#{menuId}
AND m.deleted_at IS NULL AND m.status = 'ACTIVE' AND m.scope <> 'ADMIN' AND ( mf.feature_code IS NULL OR ( tf.enabled = TRUE AND (tf.effective_from IS NULL OR tf.effective_from <= now()) AND (tf.effective_to IS NULL OR tf.effective_to > now()) ) )

SELECT count(DISTINCT permission_code) FROM iam_permission WHERE permission_code IN
#{permissionCode}
AND status = 'ACTIVE' AND permission_code IN ( 'app-studio:application:read', 'app-studio:application:use', 'app-studio:model:use', 'identity-access:permission-request:create', 'identity-access:session:logout', 'identity-access:session:read', 'identity-access:workspace:use', 'knowledge-base:knowledge-base:read', 'knowledge-base:retrieval:query' )

SELECT CASE
         WHEN #{subjectType} = 'user' THEN (
           SELECT count(*)
           FROM iam_user
           WHERE tenant_id = #{tenantId}
             AND id = #{subjectId}
             AND status = 'ACTIVE'
             AND deleted_at IS NULL
         )
         WHEN #{subjectType} = 'role' THEN (
           SELECT count(*)
           FROM iam_role
           WHERE tenant_id = #{tenantId}
             AND id = #{subjectId}
             AND status = 'ACTIVE'
             AND deleted_at IS NULL
         )
         ELSE 0
       END

