UPDATE iam_resource_acl
SET deleted_at = now(),
    updated_at = now(),
    updated_by = #{actorId},
    version = version + 1
WHERE tenant_id = #{tenantId}
  AND resource_type = #{resourceType}
  AND resource_id = #{resourceId}
  AND permission_code = #{permissionCode}
  AND deleted_at IS NULL

